// Pour chaque ticket, on vérifie si on a déjà commenté avec la phrase d'amorce
// (= si oui, on skip)

const marker = $('Set: Config').first().json.commentMarker;
const myAccountId = $('Set: Config').first().json.myAccountId;
const jiraDomain = $('Set: Config').first().json.jiraDomain;

const issue = $input.item.json;
const comments = issue?.fields?.comment?.comments || [];

const alreadyCommented = comments.some(c => {
  const isMine = c?.author?.accountId === myAccountId;
  if (!isMine) return false;
  // ADF body : on cherche le marker dans le texte aplati
  const flatText = JSON.stringify(c?.body || '').toLowerCase();
  return flatText.includes(marker.toLowerCase());
});

// Aplatir la description (renderedFields.description = HTML, on enlève les tags)
const rawHtml = issue?.renderedFields?.description || '';
const descriptionText = rawHtml
  .replace(/<br\s*\/?>(\s*)/gi, '\n')
  .replace(/<\/p>/gi, '\n\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return {
  json: {
    issueKey: issue.key,
    issueUrl: `${jiraDomain}/browse/${issue.key}`,
    summary: issue.fields.summary,
    issueType: issue.fields.issuetype?.name || 'Story',
    reporterName: issue.fields.reporter?.displayName || 'Inconnu',
    reporterAccountId: issue.fields.reporter?.accountId || '',
    descriptionText: descriptionText || '(pas de description)',
    alreadyCommented,
  },
};

// Parse la réponse de Claude et construit l'URL du formulaire

const claudeResponse = $input.item.json;
const rawText = claudeResponse?.content?.[0]?.text || '';

// Tentative robuste de parsing : Claude peut parfois entourer de markdown
let questions = [];
try {
  // Cherche le premier { et le dernier } pour extraire le JSON même si entouré de texte
  const firstBrace = rawText.indexOf('{');
  const lastBrace = rawText.lastIndexOf('}');
  if (firstBrace === -1 || lastBrace === -1) throw new Error('Pas de JSON trouvé');
  const jsonStr = rawText.substring(firstBrace, lastBrace + 1);
  const parsed = JSON.parse(jsonStr);
  questions = parsed.questions || [];
} catch (e) {
  // Fallback : on découpe par lignes commençant par - ou *
  questions = rawText
    .split('\n')
    .map(l => l.replace(/^[-*\d.\s]+/, '').trim())
    .filter(l => l.endsWith('?') && l.length > 10);
}

if (questions.length === 0) {
  questions = ['(Erreur de génération — pose tes questions à la main)'];
}

// Récupère les infos du ticket depuis le node Prepare
const prep = $('Code: Prepare + flatten').item.json;
const config = $('Set: Config').first().json;

// Encode payload pour le formulaire
const payload = {
  k: prep.issueKey,
  s: prep.summary,
  r: prep.reporterAccountId,
  rn: prep.reporterName,
  q: questions,
};
const dataParam = Buffer.from(JSON.stringify(payload), 'utf-8').toString('base64url');
const formFullUrl = `${config.formUrl}?data=${dataParam}`;

// Tronque la description pour Slack (limite 3000 chars par bloc)
const descShort = prep.descriptionText.length > 1500
  ? prep.descriptionText.substring(0, 1500) + '…'
  : prep.descriptionText;

return {
  json: {
    issueKey: prep.issueKey,
    issueUrl: prep.issueUrl,
    summary: prep.summary,
    reporterName: prep.reporterName,
    descriptionShort: descShort,
    questions,
    questionsBulleted: questions.map((q, i) => `${i + 1}. ${q}`).join('\n'),
    formFullUrl,
    slackWebhookUrl: config.slackWebhookUrl,
  },
};

